using System;

namespace StdbModule;

public static partial class TurkishQuotes
{
    public static class AhmetHamdiTanpınar
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Mazi daima mevcuttur. Kendimiz olarak yaşayabilmek için, onunla her an hesaplaşmaya ve anlaşmaya mecburuz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Beş Şehir'in asıl konusu hayatımızda kaybolan şeylerin ardından duyulan üzüntü ile yeniye karşı beslenen iştiyaktır", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bu kapalı kış aylarının beslediği sohbet yüzünden hemen her Erzurumlu biraz nükteci, biraz hicivcidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsan kaderinin büyük taraflarından biri de, bugün attığı adımın kendisini nereye götüreceğini bilmemesidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hemen herkesin yalnız kendisinin anlatabileceği bir hikâyesi vardı. Hemen herkes birkaç kişiye ağlıyor ve âkıbetini hâlâ bilmediği bir sevdiğini bekliyordu.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hiçbir şey kendi alın teri kadar bir insanı tatmin edemez. Çalışan insan kendi varlığında hüküm süren bir âhengi bütün kainata nakleder. Hayatın biricik nizamı bu ahengin kendisi olmalıdır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Konya bozkırın tam çocuğudur. Onun gibi kendini gizleyen bir güzelliği vardır. Bozkır kendine bir serap çeşnisi vermekten hoşlanır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bursa, Türk ruhunun en halis ölçülerine kendiliğinden sahiptir, denebilir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Ben hayatın susan ve değişmeyen kardeşiyim. Vazifesini hakkıyla yapan fâninin alnına bir sükûn ve sükûnet çelengi gibi uzanırım.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bütün hilkat, geniş ve eşsiz kudretinde canı sıkılan bir tanrının kendi kendini eğlendirmek için icat ettiği bir oyundur.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İstanbul, ya hiç sevilmez; yahut çok sevilmiş bir kadın gibi sevilir; yani her haline, her hususiyetine ayrı bir dikkatle, çıldırarak.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Çünkü sanat da aşk gibidir; kandırmaz, susatır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "En büyük meselemiz budur; mazi ile nerede ve nasıl bağlanacağız, hepimiz bir şuur ve benlik buhranının çocuklarıyız, hepimiz Hamlet'ten daha keskin bir \"olmak veya olmamak\" davası içinde yaşıyoruz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İstanbul daima fakiri bol bir memleketti.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bir ağacın ölümü, büyük bir mimarî eserin kaybı gibi bir şeydir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Değişmeyecek olan, hayata şekil veren, ona bizim damgamızı basan şeylerdir", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Mesuliyetini taşıyacağın fikrin adamı ol! Onu kendi uzviyetinde bir ağaç gibi yetiştir. Onun etrafında bir bahçıvan gibi sabırlı ve dikkatli çalış!", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bir taraftan iyi kötü bir tekniği almağa, onun adamı olmağa çalışıyoruz. Onun zihniyetini benimserken zaruri olarak eski kıymetleri atıyoruz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kendimizi sevmiyoruz. Kafamız bir yığın mukayeselerle dolu; Dede’yi, Wagner olmadığı için, Yunus Emre’yi, Verlaine, Bâki’yi, Goethe ve Gide yapamadığımız için beğenmiyoruz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Memleketimizde zihnî bir tembellik var. Bir safsata gibi görünecek ama ıstırabsız ve meselesiz yaşıyoruz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Düşünce, sanat, yaşama aşkı, hepsi sende toplandı. Hepsi, senin hüvviyetinde birleşti. Senin dışında düşünememek hastalığına müptelâyım.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Her düşüşün altında bir başkası vardır. Ve herkes kendinin mezarıdır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kim bilir? Belki de bazı kapıların bize kapalı görünmesi, önünde değil, arkasında bulunduğumuz içindir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kendi kendime biz gurbetin insanlarıyız diyorum. Mesafelerin terbiye ettiği insanlar...", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Vatan ve millet, vatan ve millet oldukları için sevilir. Bir din, din olarak münakaşa edilir, ret veya kabul edilir. Yoksa, hayatımıza getireceği kolaylıklar için değil.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Haksızlığı her kabul ediş, daha büyüğünü doğuruyor.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Ben aşktan daima kaçtım. Hiç sevmedim. Belki bir eksiğim oldu. Fakat rahatım. Aşkın kötü tarafı insanlara verdiği zevki eninde sonunda ödetmesidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Dinlemesini biliyorsun, ki bu mühim bir meziyettir. Hiçbir işe yaramasa bile insanın boşluğunu örter, karşısındakiyle aynı seviyeye çıkarır!", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bazen düşünüyorum, ne garip mahluklarız? Hepimiz ömrümüzün kısalığından şikayet ederiz; fakat gün denen şeyi bir an evvel ve farkına varmadan harcamak için neler yapmayız?", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Realist olmak hiç de hakikati olduğu gibi görmek değildir. Belki onunla en faydalı şekilde münasebetimizi tayin etmektir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsanların saadet anlayışları da gariptir. Kitaplara bakarsınız, kendilerini dinlersiniz, insanoğlunun asıl vasfı akıldır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bütün hayatım boyunca dikkat ettim, insanın daima korktuğu şeyler başına geliyor.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bazı insanların ömrü vakit kazanmakla geçer... Ben zamana, kendi zamanıma çelme atmakla yaşıyordum.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Niçin hep fakir ve biçare adamlar dayak yer? Mesela bizim Cemal Bey'i hiç kimse dövmez.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Sabır, insanoğlunun tek kalesidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İş insanı temizliyor, güzelleştiriyor, kendisi yapıyor, etrafıyla arasında bir yığın münasebet kuruyordu. Fakat iş aynı zamanda insanı zaptediyordu.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Şu hakikatı kendi hayatım bana öğretti: İnsanoğlu, insanoğlunun cehennemidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bu daima böyledir. Hadiseler kendiliğinden unutulmaz. Onları unutturan, tesirlerini hafifleten, varsa kabahatlilerini affettiren daima öbür hadiselerdir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "En iyisi düşünmemekti. Kaçmaktı. Kendi içime kaçmak. Fakat bir içim var mıydı? Hatta ben var mıydım? Ben dediğim şey; bir yığın ihtiyaç, azap ve korku idi.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Babamın beni saatçiliğe alıştırmak istemesi, hepimiz için bir talih oldu.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Gençlerimiz ihtirassız, hatta heyecansız; gençlik birtakım meselelere açılmak, onları hararetle yaşamaktır. Boşlukta ne san'at eseri, ne de fikir olur.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Her genç enginde bir gemi gibi her an kendi kendisine \"Ben neyim?\" \"Niçin buradayım?\" \"Ne yapmak istiyorum?\" sualini sormalıdır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Modern diktatörlerin büyük vasfı hâdiselerin peşinde gitmeleridir. Mussolini de öyle yaptı. En kolay tarafı, herkesin gittiği yolu tercih etti.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bizim ortaokullarımız, liselerimiz, bazı sergilerde boşuna işleyen makinelere benzer.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Niçin kadere bu kadar bağlı olan insanlar, bir türlü ona razı olmaz?", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Sokak, evinizin kapısından başlayan hayat, ayrıldığınız zaman hüzün duyduğunuz arkadaş, bir humma gibi sizi saran macera ve yarın içine gireceğiniz kördöğüşüdür.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Muhafazakar zihniyetin bir yüzü çok yırtıcı bir didişme ise, öbür yüzü ipin ucunu bir an bıraksanız sizi nerelere götüreceği belli olmayan bir şüphedir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "En çok hataya düşenler, kendilerinden kudretlerinin üstünde şeyler isteyenler, kendilerini olduğu gibi kabul etmeyenlerdir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Az konuşmak daima iyi şeydir; fakat derli toplu olmak şartıyla.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Sizi seviyorum, size bağlıyım, demek yerine, size ait şu veya bu zaafa bağlıyım demek karşı tarafta daha iyi bir intiba bırakır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Zaman kendini ilan ediyordu. Beyhudedir, diyordu bütün bu ıstıraplar, unutmalar ve hatırlamalar, ben varken hepsi beyhudedir!", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İffet, faziletlerin en komik olanıdır.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Tesadüfler ancak bir anlık fırsat verirler. Bu anı kaybetmek ihtimali, kaybetmemek ihtimali kadar kuvvetlidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsanın kendi hayatına istikamet verecek bir fikri bulması ne kadar güç...", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Fakirlik; gözü tok, ölçülü, sağlam karakterli insanlarda bir nevi asalete benzer. Muhteris ve zevkine düşkünlerde ise daima küçültücü olur.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Belki de ölüm dediğimiz şey; tül kadar ince ve bulanık bir zarın arkasında gizlenmek, oradan etrafı dinlemek, görmek, oradan sevdiklerine hasret çekmektir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Arzular ve ihtiraslar geçince, her şey zalim ve mütearriz yokluğun aynası oluyordu.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Belki de ahlak yoktu iyilik yoktu, vazife yoktu. Hiçbir şey yoktu. Sadece bazı şeylere kabiliyetsizlik bazı şeyleri kendisine nehyetmek vardı.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Çünkü hayat da ölüm de sevdin mi, affettin mi yenilebilir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Biz evvela kelimeleri öğreniriz; sonra yaşadıkça teker teker manâlarını.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hayat kimsenin etra­fında dönmez, herkesle beraber yürür.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Fikirlerimiz onları taşıyacak kudrette olduğumuz nispette bizimdirler.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hâlbuki kitaplar, sevginin birleştirici bir şey olduğunu yazıyorlardı.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kitap unutulmaya razıdır, fakat kadın razı olmaz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Açık havada ölmek, cam arkasında boğulmaktan daha iyidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kendi kendinizi tanımağa başladıktan sonra beğenmemeniz kadar tabii ne olabilir?", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Kendi eliyle çalışmak ruhu tasfiye eder, insanı Allah’a yaklaştırır. Dikkatini elindeki işe verirsen temiz kalırsın.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "\"Olduğumuz gibi\" ile \"olmak istediğimiz gibi\" terazinin iki kefesidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bu tek adam otuz milyona göz açtırmıyor. Bütün hayat hakkını gasp etmiş. Hepimiz onun bu memleketi nasıl yıktığını biliyoruz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Sevginin, merhametin eşiğini atlayanlar, ızdırabın gömleğini dde kendiliğinden giyerler.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Ben ise dünya içinde, ileriye açık, mazi ile hesabını gören bir Türkiye'nin peşindeyim.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Ne sağcı ne solcu...", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "O gün Şişli Camii'nin imam odasında küçük bir kerevete oturmuş, arkadaşının ölümüne ağlayan insan ise çok başka insandı. Onun elini öperken Orhan Gazi cinsinden bir adamın elini öpüyorum sandım.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Çalışmak, zamanına sahip olmak, onu kullanmasını bilmektir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Sabır, insanoğlunun tek kalesidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsanoğlu her şeyden evvel, mesuliyet hissidir ve fikirlerinin mahsulüdür. Ondan mahrum edilen insan, kendiliğinden bir paçavra haline düşer.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Aşkın kötü tarafı insanlara verdiği zevki, eninde sonunda ödetmesidir. Şu veya bu şekilde. Fakat daima ödersiniz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Çocuğu kendisi olmasında elbette rahat bırakmalı. Fakat yaşının üstüne çıkması imkânları da daima verilmeli, hattâ biraz da zorlamalı.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Etrafınızdaki çocuklarla, kendinizden küçüklerle konuşmağa tenezzül edin! Onlara anlatın! Herşeyi bilsinler! Siz onların bir hiç yüzünden ne kadar azab çektiklerini bilmezsiniz", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Yalnız dostluk sarayının çatlağı yoktur ve damı akmaz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsanda ekonomi fikri olmayınca, sade para değil, asıl kıymetlisi zaman da kayboluyor.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hayatı yapmak isteyenler, kendilerini cömertçe ona bağışlamalıdırlar.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Az konuşmak daima iyi şeydir; fakat derli toplu olmak şartıyla.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Gençlerimizin birçok eksikliği, umumî kültür seviyesinin düşüklüğünden geliyor.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İstanbul'da her saat, bir san'at eseri gibi güzeldir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "İnsanın olabileceği şeyi seçip ona çalışması ne iyi şey, ne mazhariyet.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Biz sadece imanıyla ve ruhunun cömertliğiyle yaşamış bir milletiz.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Bir lise kadrosu, millî hayatta en mühim rolü oynayan en mühim ekiptir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Tarih, şahsiyetin ta kendisidir. Onsuz insan teşekkül edemez. Cemiyet için mazi yani tarih, fert için hafıza gibidir.", Author = "Ahmet Hamdi Tanpınar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Ahmet_Hamdi_Tanpınar", Text = "Hiç kimse değişime karşı değildir, yeter ki ucu kendisine dokunmasın.", Author = "Ahmet Hamdi Tanpınar" },
        };
    }
